:root {
    --bg-primary: #121212;
    --bg-secondary: #1e1e1e;
    --bg-tertiary: #2a2a2a;

    --text-primary: #ffffff;
    --text-secondary: #b3b3b3;

    --accent-color: #03dac6;
    --accent-hover: #01b1a0;
    --danger-color: #cf6679;

    --font-heading: 'Helvetica Neue', Helvetica, Arial, sans-serif;
    --font-body: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;

    --transition: all 0.3s ease;
    --border-radius: 4px;
}

/* Reset & Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    background-color: var(--bg-primary);
    color: var(--text-primary);
    font-family: var(--font-body);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-heading);
    font-weight: 700;
    letter-spacing: 1px;
    margin-bottom: 1rem;
}

a {
    color: var(--text-primary);
    text-decoration: none;
    transition: var(--transition);
}

a:hover {
    color: var(--accent-color);
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

ul {
    list-style: none;
}

button {
    cursor: pointer;
    background: none;
    border: none;
    font-family: inherit;
    color: inherit;
}

/* Utility Classes */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--accent-color);
    color: var(--bg-primary);
    padding: 8px;
    z-index: 1000;
}

.skip-link:focus {
    top: 0;
    outline: 2px solid var(--text-primary);
}

/* Header */
.site-header {
    background-color: rgba(18, 18, 18, 0.95);
    border-bottom: 1px solid var(--bg-tertiary);
    position: sticky;
    top: 0;
    z-index: 100;
    backdrop-filter: blur(10px);
}

.header-container {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 20px;
    max-width: 1200px;
    margin: 0 auto;
}

.logo a {
    font-size: 1.5rem;
    font-weight: bold;
    letter-spacing: 2px;
}

.main-nav {
    flex: 1;
    display: flex;
    justify-content: center;
}

.menu-toggle {
    display: none;
    font-size: 1.5rem;
    padding: 5px;
}

.menu-toggle:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 2px;
}

.nav-list {
    display: flex;
    gap: 30px;
}

.nav-list a {
    text-transform: uppercase;
    font-size: 0.9rem;
    font-weight: 600;
    position: relative;
}

.nav-list a::after {
    content: '';
    position: absolute;
    bottom: -5px;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--accent-color);
    transition: width 0.3s;
}

.nav-list a:hover::after,
.nav-list a:focus-visible::after {
    width: 100%;
}

.nav-list a:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 4px;
}

.header-actions {
    display: flex;
    gap: 15px;
}

.action-btn {
    font-size: 1.2rem;
    position: relative;
    padding: 5px;
}

.action-btn:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 2px;
}

.cart-count {
    position: absolute;
    top: -5px;
    right: -10px;
    background-color: var(--accent-color);
    color: var(--bg-primary);
    font-size: 0.7rem;
    font-weight: bold;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
}

/* Buttons */
.cta-button {
    display: inline-block;
    background-color: var(--accent-color);
    color: var(--bg-primary);
    padding: 12px 24px;
    text-transform: uppercase;
    font-weight: bold;
    letter-spacing: 1px;
    border-radius: var(--border-radius);
    border: 2px solid var(--accent-color);
}

.cta-button:hover,
.cta-button:focus-visible {
    background-color: transparent;
    color: var(--accent-color);
}

.cta-button.outline {
    background-color: transparent;
    color: var(--text-primary);
    border-color: var(--text-primary);
}

.cta-button.outline:hover,
.cta-button.outline:focus-visible {
    background-color: var(--text-primary);
    color: var(--bg-primary);
}

.cta-button:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 4px;
}

/* Hero Section */
.hero {
    height: 80vh;
    min-height: 500px;
    background: linear-gradient(rgba(0, 0, 0, 0.6), rgba(0, 0, 0, 0.6)), url('https://images.unsplash.com/photo-1441984904996-e0b6ba687e04?ixlib=rb-4.0.3&auto=format&fit=crop&w=1600&q=80') center/cover no-repeat;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 0 20px;
}

.hero-content {
    max-width: 800px;
}

.hero h1 {
    font-size: clamp(2.5rem, 5vw, 4.5rem);
    text-transform: uppercase;
    margin-bottom: 20px;
}

.hero p {
    font-size: 1.2rem;
    color: var(--text-secondary);
    margin-bottom: 30px;
}

/* Sections Common */
section {
    padding: 80px 0;
}

section h2 {
    font-size: 2.5rem;
    text-align: center;
    margin-bottom: 50px;
    text-transform: uppercase;
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 30px;
}

.product-card {
    background-color: var(--bg-secondary);
    border-radius: var(--border-radius);
    overflow: hidden;
    transition: transform 0.3s;
    border: 1px solid var(--bg-tertiary);
}

.product-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 10px 20px rgba(0,0,0,0.5);
}

.product-image {
    position: relative;
    aspect-ratio: 4/5;
    overflow: hidden;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.sale-badge {
    position: absolute;
    top: 10px;
    left: 10px;
    background-color: var(--danger-color);
    color: white;
    padding: 5px 10px;
    font-size: 0.8rem;
    font-weight: bold;
    border-radius: var(--border-radius);
    z-index: 10;
}

.product-info {
    padding: 20px;
    display: flex;
    flex-direction: column;
    align-items: center;
}

.product-name {
    font-size: 1.1rem;
    margin-bottom: 10px;
    text-align: center;
}

.price-container {
    display: flex;
    gap: 10px;
    margin-bottom: 15px;
}

.product-price {
    font-weight: bold;
    color: var(--text-secondary);
    margin-bottom: 15px;
}

.price-container .product-price {
    margin-bottom: 0;
}

.sale-price {
    color: var(--danger-color);
}

.add-to-cart-btn {
    width: 100%;
    background-color: var(--bg-tertiary);
    color: var(--text-primary);
    padding: 10px;
    text-transform: uppercase;
    font-weight: bold;
    border-radius: var(--border-radius);
    border: 1px solid var(--bg-tertiary);
    transition: var(--transition);
}

.add-to-cart-btn:hover,
.add-to-cart-btn:focus-visible {
    background-color: var(--accent-color);
    color: var(--bg-primary);
    border-color: var(--accent-color);
}

.add-to-cart-btn:focus-visible {
    outline: 2px solid var(--text-primary);
    outline-offset: 2px;
}

/* Deals Section */
.deals-section {
    background-color: var(--bg-secondary);
}

.deals-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 50px;
    align-items: center;
}

.deals-text h2 {
    text-align: left;
    margin-bottom: 20px;
}

.deals-text p {
    color: var(--text-secondary);
    font-size: 1.1rem;
    margin-bottom: 30px;
}

.deal-card {
    max-width: 400px;
    margin: 0 auto;
}

/* Editorial Section */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    gap: 30px;
}

.editorial-card {
    position: relative;
    border-radius: var(--border-radius);
    overflow: hidden;
    aspect-ratio: 16/9;
}

.editorial-card img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.editorial-card:hover img {
    transform: scale(1.05);
}

.editorial-content {
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    padding: 30px;
    background: linear-gradient(transparent, rgba(0,0,0,0.9));
    z-index: 10;
}

.editorial-content h3 {
    font-size: 1.5rem;
    margin-bottom: 10px;
}

.editorial-content p {
    color: var(--text-secondary);
