    font-size: 0.9rem;
    font-weight: 600;
    position: relative;
}

.nav-list a::after {
    content: '';
    position: absolute;
    bottom: -5px;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--accent-color);
    transition: width 0.3s;
}

.nav-list a:hover::after,
.nav-list a:focus-visible::after {
    width: 100%;
}

.nav-list a:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 4px;
}

.header-actions {
    display: flex;
    gap: 15px;
}

.action-btn {
    font-size: 1.2rem;
    position: relative;
    padding: 5px;
}

.action-btn:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 2px;
}

.cart-count {
    position: absolute;
    top: -5px;
    right: -10px;
    background-color: var(--accent-color);
    color: var(--bg-primary);
    font-size: 0.7rem;
    font-weight: bold;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
}

/* Buttons */
.cta-button {
    display: inline-block;
    background-color: var(--accent-color);
    color: var(--bg-primary);
    padding: 12px 24px;
    text-transform: uppercase;
    font-weight: bold;
    letter-spacing: 1px;
    border-radius: var(--border-radius);
    border: 2px solid var(--accent-color);
}

.cta-button:hover,
.cta-button:focus-visible {
    background-color: transparent;
    color: var(--accent-color);
}

.cta-button.outline {
    background-color: transparent;
    color: var(--text-primary);
    border-color: var(--text-primary);
}

.cta-button.outline:hover,
.cta-button.outline:focus-visible {
    background-color: var(--text-primary);
    color: var(--bg-primary);
}

.cta-button:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 4px;
}

/* Hero Section */
.hero {
    height: 80vh;
    min-height: 500px;
    background: linear-gradient(rgba(0, 0, 0, 0.6), rgba(0, 0, 0, 0.6)), url('https://images.unsplash.com/photo-1441984904996-e0b6ba687e04?ixlib=rb-4.0.3&auto=format&fit=crop&w=1600&q=80') center/cover no-repeat;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 0 20px;
}

.hero-content {
    max-width: 800px;
}

.hero h1 {
    font-size: clamp(2.5rem, 5vw, 4.5rem);
    text-transform: uppercase;
    margin-bottom: 20px;
}

.hero p {
    font-size: 1.2rem;
    color: var(--text-secondary);
    margin-bottom: 30px;
}

/* Sections Common */
section {
    padding: 80px 0;
}

section h2 {
    font-size: 2.5rem;
    text-align: center;
    margin-bottom: 50px;
    text-transform: uppercase;
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 30px;
}

.product-card {
    background-color: var(--bg-secondary);
    border-radius: var(--border-radius);
    overflow: hidden;
    transition: transform 0.3s;
    border: 1px solid var(--bg-tertiary);
}

.product-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 10px 20px rgba(0,0,0,0.5);
}

.product-image {
    position: relative;
    aspect-ratio: 4/5;
    overflow: hidden;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.sale-badge {
    position: absolute;
    top: 10px;
    left: 10px;
    background-color: var(--danger-color);
    color: white;
    padding: 5px 10px;
    font-size: 0.8rem;
    font-weight: bold;
    border-radius: var(--border-radius);
    z-index: 10;
}

.product-info {
    padding: 20px;
    display: flex;
    flex-direction: column;
    align-items: center;
}

.product-name {
    font-size: 1.1rem;
    margin-bottom: 10px;
    text-align: center;
}

.price-container {
    display: flex;
    gap: 10px;
    margin-bottom: 15px;
}

.product-price {
    font-weight: bold;
    color: var(--text-secondary);
    margin-bottom: 15px;
}

.price-container .product-price {
    margin-bottom: 0;
}

.sale-price {
    color: var(--danger-color);
}

.add-to-cart-btn {
    width: 100%;
    background-color: var(--bg-tertiary);
    color: var(--text-primary);
    padding: 10px;
    text-transform: uppercase;
    font-weight: bold;
    border-radius: var(--border-radius);
    border: 1px solid var(--bg-tertiary);
    transition: var(--transition);
}

.add-to-cart-btn:hover,
.add-to-cart-btn:focus-visible {
    background-color: var(--accent-color);
    color: var(--bg-primary);
    border-color: var(--accent-color);
}

.add-to-cart-btn:focus-visible {
    outline: 2px solid var(--text-primary);
    outline-offset: 2px;
}

/* Deals Section */
.deals-section {
    background-color: var(--bg-secondary);
}

.deals-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 50px;
    align-items: center;
}

.deals-text h2 {
    text-align: left;
    margin-bottom: 20px;
}

.deals-text p {
    color: var(--text-secondary);
    font-size: 1.1rem;
    margin-bottom: 30px;
}

.deal-card {
    max-width: 400px;
    margin: 0 auto;
}

/* Editorial Section */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    gap: 30px;
}

.editorial-card {
    position: relative;
    border-radius: var(--border-radius);
    overflow: hidden;
    aspect-ratio: 16/9;
}

.editorial-card img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.editorial-card:hover img {
    transform: scale(1.05);
}

.editorial-content {
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    padding: 30px;
    background: linear-gradient(transparent, rgba(0,0,0,0.9));
    z-index: 10;
}

.editorial-content h3 {
    font-size: 1.5rem;
    margin-bottom: 10px;
}

.editorial-content p {
    color: var(--text-secondary);
    margin-bottom: 15px;
}

.read-more {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-weight: bold;
    text-transform: uppercase;
    font-size: 0.9rem;
}

.read-more i {
    transition: transform 0.3s;
}

.read-more:hover i,
.read-more:focus-visible i {
    transform: translateX(5px);
}

.read-more:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 4px;
}

/* Footer */
.site-footer {
    background-color: var(--bg-secondary);
    border-top: 1px solid var(--bg-tertiary);
    padding: 60px 0 20px;
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1.5fr;
    gap: 40px;
    margin-bottom: 60px;
}

.footer-brand p {
    color: var(--text-secondary);
    margin-top: 15px;
    max-width: 300px;
}

.footer-links h3, .footer-newsletter h3 {
    margin-bottom: 20px;
    font-size: 1.2rem;
}

.footer-links ul li {
    margin-bottom: 10px;
}

.footer-links a {
    color: var(--text-secondary);
}

.footer-links a:hover,
.footer-links a:focus-visible {
    color: var(--accent-color);
}

.footer-links a:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 2px;
}

.footer-newsletter p {
    color: var(--text-secondary);
    margin-bottom: 20px;
}

.newsletter-form {
    display: flex;
}

.newsletter-form input {
    flex: 1;
    padding: 10px 15px;
    background-color: var(--bg-tertiary);
    border: 1px solid var(--bg-tertiary);
    color: var(--text-primary);
    border-radius: var(--border-radius) 0 0 var(--border-radius);
    outline: none;
}

.newsletter-form input:focus {
    border-color: var(--accent-color);
}

.newsletter-form button {
    background-color: var(--accent-color);
    color: var(--bg-primary);
    padding: 10px 20px;
    font-weight: bold;
    border-radius: 0 var(--border-radius) var(--border-radius) 0;
    transition: var(--transition);
}

.newsletter-form button:hover,
.newsletter-form button:focus-visible {
    background-color: var(--accent-hover);
}

.newsletter-form button:focus-visible {
    outline: 2px solid var(--text-primary);
    outline-offset: 2px;
}

.footer-bottom {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 20px;
    border-top: 1px solid var(--bg-tertiary);
    color: var(--text-secondary);
    font-size: 0.9rem;
}

.social-links {
    display: flex;
    gap: 15px;
}

.social-links a {
    color: var(--text-secondary);
    font-size: 1.2rem;
}

.social-links a:hover,
.social-links a:focus-visible {
    color: var(--accent-color);
}

.social-links a:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 4px;
}

/* Responsive */
@media (max-width: 992px) {
    .deals-content {
        grid-template-columns: 1fr;
    }

    .deals-text h2 {
        text-align: center;
    }

    .deals-text p {
        text-align: center;
    }

    .deals-text .cta-button {
        display: block;
        width: max-content;
        margin: 0 auto;
    }

    .footer-grid {
        grid-template-columns: 1fr 1fr;
    }
}

@media (max-width: 768px) {
    .menu-toggle {
        display: block;
    }

    .main-nav {
        order: -1;
        flex: 0;
    }

    .nav-list {
        display: none; /* Hide by default on mobile */
        position: absolute;
        top: 100%;
        left: 0;
        width: 100%;
        background-color: var(--bg-secondary);
        flex-direction: column;
        gap: 0;
        padding: 20px 0;
        border-bottom: 1px solid var(--bg-tertiary);
    }

    .nav-list.active {
        display: flex;
    }

    .nav-list a {
        display: block;
        padding: 15px 20px;
        text-align: center;
    }

    .header-container {
        justify-content: space-between;
    }

    .logo {
        position: absolute;
        left: 50%;
        transform: translateX(-50%);
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .editorial-card {
        aspect-ratio: 4/3;
    }
}

@media (max-width: 576px) {
    .footer-grid {
        grid-template-columns: 1fr;
    }

    .footer-bottom {
        flex-direction: column;
        gap: 20px;
        text-align: center;
    }

    .hero h1 {
        font-size: 2rem;
    }
}

/* Accessibility features */
@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

/* Forced Colors (High Contrast) Mode Support */
@media (forced-colors: active) {
    .cta-button, .add-to-cart-btn, .newsletter-form button {
        border: 2px solid ButtonText;
    }

    .nav-list a::after {
        background-color: SelectedItem;
    }

    .sale-badge {
        border: 1px solid ButtonText;
    }
}

document.addEventListener('DOMContentLoaded', () => {
    // Mobile Navigation Toggle
    const menuToggle = document.querySelector('.menu-toggle');
    const navList = document.getElementById('nav-list');

    if (menuToggle && navList) {
        menuToggle.addEventListener('click', () => {
            const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
            menuToggle.setAttribute('aria-expanded', !isExpanded);
            navList.classList.toggle('active');

            // Toggle icon
            const icon = menuToggle.querySelector('i');
            if (isExpanded) {
                icon.classList.remove('fa-times');
                icon.classList.add('fa-bars');
            } else {
                icon.classList.remove('fa-bars');
                icon.classList.add('fa-times');
            }
        });

        // Close menu when clicking outside
        document.addEventListener('click', (e) => {
            if (!menuToggle.contains(e.target) && !navList.contains(e.target) && navList.classList.contains('active')) {
                menuToggle.setAttribute('aria-expanded', 'false');
                navList.classList.remove('active');

                const icon = menuToggle.querySelector('i');
                icon.classList.remove('fa-times');
                icon.classList.add('fa-bars');
            }
        });

        // Close menu when Escape key is pressed
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && navList.classList.contains('active')) {
                menuToggle.setAttribute('aria-expanded', 'false');
                navList.classList.remove('active');
                menuToggle.focus();

                const icon = menuToggle.querySelector('i');
                icon.classList.remove('fa-times');
                icon.classList.add('fa-bars');
            }
        });
    }

    // Cart Functionality
    const addToCartBtns = document.querySelectorAll('.add-to-cart-btn');
    const cartCountElement = document.querySelector('.cart-count');
    let cartCount = 0;

    addToCartBtns.forEach(btn => {
        btn.addEventListener('click', function() {
            // Update cart count
            cartCount++;
            cartCountElement.textContent = cartCount;

            // Visual feedback
            const originalText = this.textContent;
            this.textContent = 'Added!';
            this.style.backgroundColor = 'var(--accent-color)';
            this.style.color = 'var(--bg-primary)';

            // Announce to screen readers (creating a polite live region if it doesn't exist)
            let announcer = document.getElementById('cart-announcer');
            if (!announcer) {
                announcer = document.createElement('div');
                announcer.id = 'cart-announcer';
                announcer.className = 'sr-only';
                announcer.setAttribute('aria-live', 'polite');
                document.body.appendChild(announcer);
            }
            const productName = this.closest('.product-card').querySelector('.product-name').textContent;
            announcer.textContent = `${productName} added to cart. Cart now has ${cartCount} items.`;

            // Reset button after 2 seconds
            setTimeout(() => {
                this.textContent = originalText;
                this.style.backgroundColor = '';
                this.style.color = '';
            }, 2000);
        });
    });

    // Newsletter Submission
    const newsletterForm = document.querySelector('.newsletter-form');
    if (newsletterForm) {
        newsletterForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const input = newsletterForm.querySelector('input[type="email"]');

            if (input.value) {
                // Mock submission
                const btn = newsletterForm.querySelector('button');
                const originalBtnText = btn.textContent;
                btn.textContent = 'Subscribed!';
                input.value = '';

                setTimeout(() => {
                    btn.textContent = originalBtnText;
                }, 3000);
            }
        });
    }
});

