    outline: 2px solid var(--accent-color);
    outline-offset: 2px;
}

.nav-list {
    display: flex;
    gap: 30px;
}

.nav-list a {
    text-transform: uppercase;
    font-size: 0.9rem;
    font-weight: 600;
    position: relative;
}

.nav-list a::after {
    content: '';
    position: absolute;
    bottom: -5px;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--accent-color);
    transition: width 0.3s;
}

.nav-list a:hover::after,
.nav-list a:focus-visible::after {
    width: 100%;
}

.nav-list a:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 4px;
}

.header-actions {
