    font-size: 0.7rem;
    font-weight: bold;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
}

/* Buttons */
.cta-button {
    display: inline-block;
    background-color: var(--accent-color);
    color: var(--bg-primary);
    padding: 12px 24px;
    text-transform: uppercase;
    font-weight: bold;
    letter-spacing: 1px;
    border-radius: var(--border-radius);
