}

.product-name {
    font-size: 1.1rem;
    margin-bottom: 10px;
    text-align: center;
}

.price-container {
    display: flex;
    gap: 10px;
    margin-bottom: 15px;
}

.product-price {
    font-weight: bold;
    color: var(--text-secondary);
    margin-bottom: 15px;
}

.price-container .product-price {
    margin-bottom: 0;
}

.sale-price {
    color: var(--danger-color);
}

.add-to-cart-btn {
    width: 100%;
    background-color: var(--bg-tertiary);
    color: var(--text-primary);
    padding: 10px;
    text-transform: uppercase;
