    background-color: var(--bg-secondary);
}

.deals-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 50px;
    align-items: center;
}

.deals-text h2 {
    text-align: left;
    margin-bottom: 20px;
}

.deals-text p {
    color: var(--text-secondary);
    font-size: 1.1rem;
    margin-bottom: 30px;
}

.deal-card {
    max-width: 400px;
    margin: 0 auto;
}

