}

.editorial-content h3 {
    font-size: 1.5rem;
    margin-bottom: 10px;
}

.editorial-content p {
    color: var(--text-secondary);
    margin-bottom: 15px;
}

.read-more {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-weight: bold;
    text-transform: uppercase;
    font-size: 0.9rem;
}

.read-more i {
    transition: transform 0.3s;
}

.read-more:hover i,
.read-more:focus-visible i {
    transform: translateX(5px);
}

.read-more:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 4px;
}

